from __future__ import annotations; from datetime import date
def test_brokerage_position_prefers_ticker_over_company_name(): from src.extraction.extension.brokerage_positions import _parse_structured_positions; payload = {'currency': 'USD', 'positions': [{'asset_identifier': 'Synthetic Chips Incorporated', 'symbol': 'SYNC', 'quantity': '100', 'market_value': '12345.00', 'currency': 'USD'}]}; snapshots = _parse_structured_positions(payload, broker='SynthBroker', snapshot_date=date(2025, 6, 30)); assert len(snapshots) == 1; assert snapshots[0].asset_identifier == 'SYNC', f"expected ticker 'SYNC' to win, got {snapshots[0].asset_identifier!r} (company name leaked into asset_identifier -> breaks market-data sync)"
